// Prueba diaria: en cada agencia un contacto de prueba (DND, sin teléfono: no se manda nada por WhatsApp)
// escribe como si viniera de un anuncio y se comprueba que la IA lo lleve a "Datos completos". Después se borra todo.
const AG = {
  independencia: { loc: '2O4BBoTVOs95TgWbel6e', webhook: 'rsindependencia', memoria: 'RS-Independencia', buffer: 'RSIndependencia_buffer', crm: '16PKHFb_SovGwvWNcLknX8rK68UydPchs46irNxcqgDA', pestana: '4rto 2026', completo: '06ee9f24-864a-47de-9f04-51e6eddd3bc5' },
  centro: { loc: 'oC2FNTV3Dc5yhLyrGvoy', webhook: 'Rscentro', memoria: 'RS-Centro', buffer: 'RSCentro_buffer', crm: '1KncjwB2O5Yn8X2V_7t74_QrqulNU6dUe5lVmBM36nFw', pestana: '4rto 2026', completo: '5c6973d5-a28f-44e1-8224-b143c5d0866b' },
  periodismo: { loc: 'Jf5jBydZMO0fdMeo1d4O', webhook: 'rsperiodismov2', memoria: 'RS-Periodismo', buffer: 'RSPeriodismo_buffer', crm: '1-LlxUtAyCdgVPphw7vq8XOQmVgJ0-sSBZmOmuASt-OM', pestana: '4rto 2026', completo: 'bba4dea4-89ab-4354-9844-4b8a92cfb23e' },
  matriz: { loc: 'UIJiu5Wa9iPVzMpbaZcx', webhook: 'rsmatriz', memoria: 'RsViajes_Matriz', buffer: 'RSMatriz_buffer', crm: '115Sb7xbszY-G7VnnemThDPLd7i8TwxhNStr1Dcdi2x4', pestana: '2026', completo: '0bdff55d-f090-421c-8ed2-731927c4ec7f' },
  hijar: { loc: '4xUuPucjdj14sqVme6sO', webhook: 'Rshijar', memoria: 'RS-Hijar', buffer: 'RSHijar_buffer', crm: '1FIMJ_ic8I6-uHreO-zugSGJZllCMlqAT6q779qmZias', pestana: '4rto 2026', completo: '3c415459-1969-434b-b0f5-ba6d9658afe2' },
};
const marca = $now.setZone('America/Mexico_City').toFormat('yyyyMMddHHmm');
const DND = Object.fromEntries(['Call', 'Email', 'SMS', 'WhatsApp', 'GMB', 'FB'].map(k => [k, { status: 'active' }]));
return Object.entries(AG).map(([agencia, c]) => ({ json: {
  agencia, method: 'POST', path: '/contacts/',
  body: { locationId: c.loc, firstName: 'Prueba', lastName: `Diaria IA (${agencia})`, email: `prueba-diaria-${agencia}-${marca}@example.com`,
          tags: ['prueba_ia'], dnd: true, dndSettings: DND, source: 'Prueba diaria n8n' },
  ctx: { agencia, ...c },
} }));

// Mensaje de prueba con todos los datos, para una fecha dentro de unos 2 meses
const MESES = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const ida = $now.setZone('America/Mexico_City').plus({ days: 60 }), vuelta = ida.plus({ days: 4 });
const fechas = ida.month === vuelta.month
  ? `del ${ida.day} al ${vuelta.day} de ${MESES[vuelta.month - 1]}`
  : `del ${ida.day} de ${MESES[ida.month - 1]} al ${vuelta.day} de ${MESES[vuelta.month - 1]}`;
const texto = `Hola, quiero cotizar Cancún ${fechas}, somos 2 adultos sin niños`;
// n8n se llama a sí mismo por la dirección interna (la pública no responde desde dentro)
return $input.all().map(it => {
  const ctx = { ...it.json.ctx, contact_id: it.json.res?.contact?.id || null, error_contacto: it.json.res?.contact?.id ? null : JSON.stringify(it.json.res).slice(0, 300), texto };
  return { json: { ctx, url: ctx.contact_id ? `http://localhost:5678/webhook/${ctx.webhook}` : '',
    body: { contact_id: ctx.contact_id || 'sin-contacto', first_name: 'Prueba', full_name: `Prueba Diaria IA (${ctx.agencia})`,
            message: { type: 2, body: texto }, contact: { lastAttributionSource: { medium: 'whatsapp', adId: '999000000000888' } } } } };
});

// ¿Contestó la IA y llegó la oportunidad a "Datos completos" con los datos del viaje?
const opps = $('Buscar oportunidad').all(), mem = $('Memoria IA').all();
return $('Preparar mensaje').all().map((it, i) => {
  const c = it.json.ctx;
  const opp = (opps[i]?.json?.res?.opportunities || [])[0];
  const m = (mem[i]?.json?.body || [])[0] || null;
  let ok = false, paso = '', detalle = '';
  if (!c.contact_id) { paso = 'Crear contacto en GHL'; detalle = c.error_contacto || ''; }
  else if (!m || !m.pregunta_anterior) { paso = 'La IA no contestó'; detalle = 'No hay respuesta guardada en Supabase'; }
  else if (!opp) { paso = 'Oportunidad'; detalle = 'No se creó la oportunidad en GHL'; }
  else if (opp.pipelineStageId !== c.completo) { paso = 'Datos completos'; detalle = `La oportunidad quedó en otra etapa (${opp.pipelineStageId}) · destino=${m.destino} salida=${m.fecha_salida} adultos=${m.Adultos}`; }
  else if (!m.destino || !m.fecha_salida || !m.Adultos) { paso = 'Datos del viaje'; detalle = `Faltan datos: destino=${m.destino} salida=${m.fecha_salida} adultos=${m.Adultos}`; }
  else { ok = true; detalle = `destino=${m.destino} salida=${m.fecha_salida} regreso=${m.fecha_regreso} adultos=${m.Adultos}`; }
  return { json: { ...c, opp_id: opp?.id || null, ok, paso, detalle, respuesta_ia: m?.pregunta_anterior || '' } };
});

// Borra la oportunidad y el contacto de prueba en GHL
const out = [];
for (const it of $('Evaluar').all()) {
  const r = it.json;
  if (r.opp_id) out.push({ json: { agencia: r.agencia, method: 'DELETE', path: `/opportunities/${r.opp_id}`, ctx: { agencia: r.agencia } } });
  if (r.contact_id) out.push({ json: { agencia: r.agencia, method: 'DELETE', path: `/contacts/${r.contact_id}`, ctx: { agencia: r.agencia } } });
}
return out.length ? out : [{ json: { vacio: true } }];

// Borra los registros de la prueba en Supabase (memoria, buffer y ventana de 72 h)
const out = [];
for (const it of $('Evaluar').all()) {
  const r = it.json;
  if (!r.contact_id) continue;
  for (const t of [r.memoria, r.buffer, 'RS_ventana_meta'])
    out.push({ json: { url: `https://fllhjemdhohsewqwzrpc.supabase.co/rest/v1/${encodeURIComponent(t)}?contact_id=eq.${r.contact_id}` } });
}
return out.length ? out : [{ json: { url: '' } }];

// Busca en el CRM las filas de la prueba (columna "Lead" = contact_id) y arma el borrado, de abajo hacia arriba
const pedidos = $('CRM pedir').all(), hojas = $('CRM hojas').all(), valores = $('CRM leer').all();
return pedidos.map((p, i) => {
  const sheet = (hojas[i]?.json?.sheets || []).find(s => s.properties.title === p.json.pestana);
  const filas = valores[i]?.json?.values || [];
  const col = (filas[0] || []).findIndex(h => String(h).trim() === 'Lead');
  const borrar = [];
  if (sheet && col >= 0) filas.forEach((f, idx) => { if (idx > 0 && f[col] === p.json.contact_id) borrar.push(idx); });
  const requests = borrar.sort((a, b) => b - a).map(idx => ({ deleteDimension: { range: { sheetId: sheet.properties.sheetId, dimension: 'ROWS', startIndex: idx, endIndex: idx + 1 } } }));
  return { json: { crm: p.json.crm, agencia: p.json.agencia, filas: borrar.length, requests } };
}).filter(x => x.json.requests.length);

// Solo si alguna agencia falló: un correo con el detalle
const r = $('Evaluar').all().map(i => i.json);
const malas = r.filter(x => !x.ok);
if (!malas.length) return [];
const N = { independencia: 'Independencia', centro: 'Centro', periodismo: 'Periodismo', matriz: 'Matriz', hijar: 'Hijar' };
const cuerpo = `La prueba diaria del sistema falló en ${malas.length} de ${r.length} agencias.

` +
  malas.map(x => `❌ ${N[x.agencia]}
   Paso: ${x.paso}
   Detalle: ${x.detalle}
   Mensaje de prueba: "${x.texto}"
   Respuesta de la IA: ${x.respuesta_ia || '(ninguna)'}`).join('

') +
  `

Bien: ${r.filter(x => x.ok).map(x => N[x.agencia]).join(', ') || 'ninguna'}.

Los contactos de prueba ya se borraron. Revisa las ejecuciones en n8n de la agencia que falló.`;
return [{ json: { asunto: `⚠️ Prueba diaria Rs Viajes: falla en ${malas.map(x => N[x.agencia]).join(', ')}`, cuerpo } }];
